use std::hint::black_box;
use std::sync::atomic::{AtomicU32, Ordering};
static HIT: AtomicU32 = AtomicU32::new(0);
#[inline(never)] pub fn col_a(_p0: isize, _p1: bool, _p2: usize, _p3: f32, _p4: i64) { HIT.store(0xA, Ordering::SeqCst); }
#[inline(never)] pub fn col_b(_p0: u8, _p1: u64, _p2: f64, _p3: u16, _p4: i8) { HIT.store(0xB, Ordering::SeqCst); }
#[inline(never)] pub fn col_c(_p0: u64, _p1: u8) { HIT.store(0xC, Ordering::SeqCst); }
#[inline(never)] fn call_as_b(f: fn(u8, u64, f64, u16, i8)) { f(1, 1, 1.0, 1, 1) }
fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    let f: fn(u8, u64, f64, u16, i8) = match mode.as_str() {
        "b" => col_b,
        "a_as_b" => unsafe { std::mem::transmute(col_a as fn(isize, bool, usize, f32, i64)) },
        "c_as_b" => unsafe { std::mem::transmute(col_c as fn(u64, u8)) },
        _ => std::process::exit(2),
    };
    call_as_b(black_box(f));
    println!("CALLEE_RAN={:X}", HIT.load(Ordering::SeqCst));
}

